const inp = $input.first().json || {};
let a = {};
try { a = inp.args ? JSON.parse(inp.args) : {}; } catch (e) { a = {}; }
const base = 'https://n8n-production-47b1.up.railway.app/api/v1';
const id = String(a.id || a.workflow_id || '').replace(/[^A-Za-z0-9]/g, '');
const PROTECTED = ['FigFCnNDE93SB62P', 'lqjYB7EP7xHmThVg', 'MfD6wYIbloXnfULA'];
let r = null, err = '';
switch (inp.action) {
  case 'list_workflows': r = { method: 'GET', url: base + '/workflows?limit=100' }; break;
  case 'recent_errors': r = { method: 'GET', url: base + '/executions?status=error&includeData=true&limit=' + Math.min(parseInt(a.limit || 8, 10) || 8, 15) }; break;
  case 'activate': if (!id) err = 'missing id'; else r = { method: 'POST', url: base + '/workflows/' + id + '/activate' }; break;
  case 'deactivate': if (!id) err = 'missing id'; else if (PROTECTED.indexOf(id) > -1) err = 'this core workflow cannot be stopped from the agent'; else r = { method: 'POST', url: base + '/workflows/' + id + '/deactivate' }; break;
  default: err = 'unknown action';
}
return [{ json: { skip: !r, error: err, action: inp.action, method: r ? r.method : 'GET', url: r ? r.url : '' } }];

const b = $('Build Request').first().json;
if (b.skip) return [{ json: { ok: false, error: b.error } }];
const res = $input.first().json || {};
const code = res.statusCode || 200;
const d = res.body || {};
if (code >= 400) return [{ json: { ok: false, error: (d && d.message) || ('HTTP ' + code) } }];
if (b.action === 'list_workflows') { const l = (d.data || []).filter(function (w) { return !w.isArchived && !/^TMP/.test(w.name || ''); }).map(function (w) { return { id: w.id, name: w.name, active: !!w.active, updated: String(w.updatedAt || '').slice(0, 16) }; }); return [{ json: { ok: true, active_count: l.filter(function (w) { return w.active; }).length, workflows: l } }]; }
if (b.action === 'recent_errors') { const l = (d.data || []).map(function (e) { const rd = (e.data && e.data.resultData) || {}; const er = rd.error || {}; return { execution_id: e.id, workflow_id: e.workflowId, workflow: (e.workflowData && e.workflowData.name) || '', at: String(e.startedAt || '').slice(0, 16), node: rd.lastNodeExecuted || (er.node && er.node.name) || '', error: String(er.message || er.description || '').slice(0, 300) }; }); return [{ json: { ok: true, errors: l } }]; }
return [{ json: { ok: true, done: b.action, workflow: d.name || '', active: d.active } }];

